#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int N = 1005;
vector<int> g[N];
int color[N]; // 0未染色 1红 2蓝

bool bfs(int st)
{
    queue<int> q;
    q.push(st);
    color[st] = 1;
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for (int v : g[u])
        {
            if (color[v] == 0)
            {
                color[v] = 3 - color[u];
                q.push(v);
            }
            else if (color[v] == color[u])
            {
                return false;
            }
        }
    }
    return true;
}

int main()
{
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; ++i)
    {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    bool ok = true;
    for (int i = 1; i <= n; ++i)
    {
        if (color[i] == 0)
        {
            if (!bfs(i))
            {
                ok = false;
                break;
            }
        }
    }
    if (ok) cout << "Yes\n";
    else cout << "No\n";
    return 0;
}
